DROP TABLE IF EXISTS `employee_loans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employee_loans` (
  `loan_id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `loan_type_id` int(11) NOT NULL,
  `account_reference` varchar(100) DEFAULT NULL,
  `provider_name` varchar(200) DEFAULT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `balance_amount` decimal(10,2) NOT NULL,
  `monthly_deduction` decimal(10,2) NOT NULL DEFAULT 0.00,
  `interest_rate` decimal(5,2) NOT NULL DEFAULT 0.00,
  `total_payable` decimal(10,2) NOT NULL DEFAULT 0.00,
  `reason` text DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `denied_reason` varchar(255) DEFAULT NULL,
  `cancelled_reason` text DEFAULT NULL,
  `return_reason` text DEFAULT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `status` enum('PENDING','ACTIVE','PAUSED','COMPLETED','CANCELLED','DENIED','ARCHIVED','RETURNED') NOT NULL DEFAULT 'PENDING',
  `filed_by` enum('ADMIN','EMPLOYEE') NOT NULL DEFAULT 'ADMIN',
  `skip_next_deduction` tinyint(1) NOT NULL DEFAULT 0,
  `next_deduction_override` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `paused_at` timestamp NULL DEFAULT NULL,
  `archived_at` timestamp NULL DEFAULT NULL,
  `archived_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`loan_id`),
  KEY `fk_loan_emp` (`employee_id`),
  KEY `fk_loan_type` (`loan_type_id`),
  KEY `fk_loan_approved_by` (`approved_by`),
  KEY `fk_el_archived_by` (`archived_by`),
  CONSTRAINT `fk_el_archived_by` FOREIGN KEY (`archived_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `fk_loan_approved_by` FOREIGN KEY (`approved_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_loan_emp` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`employee_id`),
  CONSTRAINT `fk_loan_type` FOREIGN KEY (`loan_type_id`) REFERENCES `loan_types` (`loan_type_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

