CREATE TABLE `payroll_deductions` (
  `payroll_deduction_id` int(11) NOT NULL AUTO_INCREMENT,
  `payroll_id` int(11) NOT NULL,
  `deduction_type_id` int(11) NOT NULL,
  `loan_id` int(11) DEFAULT NULL,
  `amount` decimal(10,2) NOT NULL DEFAULT 0.00,
  `is_adjustment` tinyint(1) NOT NULL DEFAULT 0,
  `adjustment_label` varchar(120) DEFAULT NULL,
  `absence_days` decimal(5,2) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`payroll_deduction_id`),
  KEY `fk_paydeduct_pay` (`payroll_id`),
  KEY `fk_paydeduct_type` (`deduction_type_id`),
  KEY `fk_pd_loan` (`loan_id`),
  CONSTRAINT `fk_paydeduct_pay` FOREIGN KEY (`payroll_id`) REFERENCES `payroll_records` (`payroll_id`),
  CONSTRAINT `fk_paydeduct_type` FOREIGN KEY (`deduction_type_id`) REFERENCES `deduction_types` (`deduction_type_id`),
  CONSTRAINT `fk_pd_loan` FOREIGN KEY (`loan_id`) REFERENCES `employee_loans` (`loan_id`)
