DROP TABLE IF EXISTS `payroll_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `payroll_settings` (
  `setting_id` int(11) NOT NULL AUTO_INCREMENT,
  `attendance_affects_payroll` tinyint(1) NOT NULL DEFAULT 0,
  `enable_undertime_deduction` tinyint(1) NOT NULL DEFAULT 0,
  `enable_overtime_pay` tinyint(1) NOT NULL DEFAULT 0,
  `payroll_frequency` enum('SEMI_MONTHLY','MONTHLY') NOT NULL DEFAULT 'SEMI_MONTHLY',
  `working_days_per_week` tinyint(4) NOT NULL DEFAULT 5,
  `cutoff1_start_day` tinyint(4) NOT NULL DEFAULT 1,
  `cutoff1_end_day` tinyint(4) NOT NULL DEFAULT 15,
  `cutoff2_start_day` tinyint(4) NOT NULL DEFAULT 16,
  `cutoff2_end_day` tinyint(4) NOT NULL DEFAULT 31,
  `weekend_pay_date_rule` enum('EXACT','ADVANCE') NOT NULL DEFAULT 'ADVANCE',
  `attendance_source` enum('MANUAL','REFERENCE','AUTO') NOT NULL DEFAULT 'REFERENCE',
  `default_paid_leave_days` decimal(5,2) NOT NULL DEFAULT 30.00,
  `leave_allocation_days` decimal(5,2) NOT NULL DEFAULT 30.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `auto_apply_allowances` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Automatically apply allowances during payroll generation',
  `auto_apply_deductions` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Automatically apply deductions during payroll generation',
  `allow_manual_override` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Allow manual override during payroll editing',
  `use_government_tables` tinyint(1) NOT NULL DEFAULT 1 COMMENT 'Use government contribution tables for auto-calculation',
  `government_calc_mode` enum('STANDARD','MANUAL') NOT NULL DEFAULT 'STANDARD' COMMENT 'Government contribution calculation mode',
  PRIMARY KEY (`setting_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
